package io.github.long0823.tclviewer;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.*;
public final class StreamRelay implements AutoCloseable {
 public interface Listener {void failed(String message);}
 private final ChannelConfig config;private final TsEpg epg;private final Listener listener;private volatile boolean closed;private volatile Socket tv;private final ServerSocket http;private volatile Client client;public volatile long bytes,reconnects,droppedBytes;private volatile boolean sourceEnded;
 private static final class Client {final Socket socket;final ArrayBlockingQueue<byte[]> queue=new ArrayBlockingQueue<>(128);volatile boolean closed;Client(Socket s){socket=s;}void close(){closed=true;queue.clear();queue.offer(new byte[0]);try{socket.close();}catch(IOException ignored){}}}
 public StreamRelay(ChannelConfig c,TsEpg e,Listener l)throws IOException{config=c;epg=e;listener=l;http=new ServerSocket(0,2,InetAddress.getByName("127.0.0.1"));}
 public String url(){return "http://127.0.0.1:"+http.getLocalPort()+"/live.ts";}
 public void start(){Thread a=new Thread(this::accept,"viewer-http");a.setDaemon(true);a.start();Thread b=new Thread(this::receive,"viewer-ts");b.setDaemon(true);b.start();}
 private void receive(){byte[] input=new byte[48128],scan=new byte[48316];long outage=0;try{while(!closed){int carry=0;try(Socket s=new Socket()){tv=s;s.connect(new InetSocketAddress(config.host,config.streamPort()),4000);s.setSoTimeout(15000);s.setReceiveBufferSize(1048576);OutputStream auth=s.getOutputStream();auth.write(("AUTH "+config.token+"\n").getBytes(StandardCharsets.US_ASCII));auth.flush();InputStream in=s.getInputStream();epg.resetAssembler();while(!closed){int n=in.read(input);if(n<0)throw new EOFException();if(n==0)continue;outage=0;bytes+=n;System.arraycopy(input,0,scan,carry,n);int total=carry+n,pos=0;ByteArrayOutputStream aligned=new ByteArrayOutputStream(total);while(!closed&&pos+188<=total){if(scan[pos]!=0x47||(pos+376<=total&&scan[pos+188]!=0x47)){pos++;continue;}epg.feed(scan,pos);aligned.write(scan,pos,188);pos+=188;}carry=total-pos;System.arraycopy(scan,pos,scan,0,carry);Client current=client;if(current!=null&&!current.closed&&aligned.size()>0){byte[] data=aligned.toByteArray();while(!current.closed&&!current.queue.offer(data)){byte[] old=current.queue.poll();if(old!=null)droppedBytes+=old.length;}}}}catch(Exception e){if(closed)break;reconnects++;if(outage==0)outage=System.nanoTime();if(System.nanoTime()-outage>TimeUnit.SECONDS.toNanos(45)){if(listener!=null)listener.failed("受信を復旧できませんでした。TVとの接続、チューナーの使用状況を確認してください。");break;}android.util.Log.i("TclViewer","Reconnecting TS after "+e.getClass().getSimpleName());try{Thread.sleep(500);}catch(InterruptedException interrupted){Thread.currentThread().interrupt();break;}}finally{tv=null;}}}finally{sourceEnded=true;Client current=client;if(current!=null)current.close();}}
 private static byte[] nullPacket(){byte[] packet=new byte[188];Arrays.fill(packet,(byte)255);packet[0]=0x47;packet[1]=0x1f;packet[2]=(byte)255;packet[3]=0x10;return packet;}
 private static final byte[] KEEPALIVE=nullPacket();
 private void accept(){while(!closed)try{Socket socket=http.accept();socket.setSoTimeout(5000);Thread t=new Thread(()->serve(socket),"viewer-player");t.setDaemon(true);t.start();}catch(IOException e){if(!closed&&listener!=null)listener.failed("再生の接続を開始できません。");}}
 private void serve(Socket socket){Client current=null;try{InputStream in=socket.getInputStream();ByteArrayOutputStream request=new ByteArrayOutputStream();int previous=0,matched=0;for(int i=0;i<4096;i++){int c=in.read();if(c<0)return;request.write(c);if((previous==13&&c==10)||(previous==10&&c==10)){matched++;if(matched==2)break;}else if(c!=13)matched=0;previous=c;}String line=request.toString("US-ASCII");boolean head=line.startsWith("HEAD /live.ts ");if(!head&&!line.startsWith("GET /live.ts "))return;OutputStream out=new BufferedOutputStream(socket.getOutputStream(),65536);out.write("HTTP/1.1 200 OK\r\nContent-Type: video/mp2t\r\nCache-Control: no-store\r\nAccept-Ranges: none\r\nConnection: close\r\n\r\n".getBytes(StandardCharsets.US_ASCII));out.flush();if(head)return;current=new Client(socket);Client old=client;if(old!=null)old.close();client=current;while(!closed&&!current.closed){byte[] data=current.queue.poll(1,TimeUnit.SECONDS);if(data==null){if(sourceEnded)break;out.write(KEEPALIVE);out.flush();continue;}if(data.length==0)break;out.write(data);out.flush();}}catch(Exception ignored){}finally{if(current!=null){current.close();if(client==current)client=null;}else try{socket.close();}catch(IOException ignored){}}}
 @Override public void close(){closed=true;Client c=client;if(c!=null)c.close();Socket s=tv;if(s!=null)try{s.close();}catch(IOException ignored){}try{http.close();}catch(IOException ignored){}}
}